 access(runId:string,hostId:string,endpoint:string):WorkItemAccess{const url=new URL(endpoint);if(!['http:','https:'].includes(url.protocol)||!['localhost','127.0.0.1','[::1]'].includes(url.hostname)||url.username||url.password||url.search||url.hash||!url.pathname.endsWith('/internal/runtime/work-items'))throw Error('invalid_work_item_endpoint');const old=this.store.one<{host_id:string;credential:string;endpoint:string}>('SELECT * FROM work_item_tool_grants WHERE run_id=?',runId);if(old){if(old.host_id!==hostId||old.endpoint!==endpoint)throw new TaskError(409,'work_item_run_binding_changed');return{version:1,runId,hostId,endpoint,credential:old.credential};}const credential=randomBytes(32).toString('base64url');this.store.run('INSERT INTO work_item_tool_grants VALUES(?,?,?,?,?)',runId,hostId,hash(credential),credential,endpoint);return{version:1,runId,hostId,endpoint,credential};}
